  ('broad_jump', 'Salto horizontal', array['broad jump', 'standing long jump', 'salto de longitud sin carrera', 'salto a pies juntos']::text[], 'functional', 'reps', array['bodyweight']::text[], false, true, 90, 'Desde parado, salta lo más lejos posible con los dos pies y aterriza estable.'),
  ('skater_jump', 'Saltos de patinador', array['skater jumps', 'skaters', 'lateral bound', 'saltos laterales', 'patinador']::text[], 'functional', 'reps', array['bodyweight']::text[], false, true, 60, 'Salta de lado de una pierna a la otra y aterriza estable sobre una.'),
