  ('med_ball_chest_pass', 'Pase de pecho con balón', array['medicine ball chest pass', 'chest pass', 'pase de pecho', 'lanzamiento de pecho']::text[], 'functional', 'weight_reps', array['medball']::text[], false, true, 60, 'Lanza el balón desde el pecho contra la pared con un empuje explosivo.'),
