  ('battle_ropes', 'Cuerdas de batalla', array['battle ropes', 'battling ropes', 'cuerdas', 'ondas con cuerdas', 'battle rope']::text[], 'functional', 'time', array['battle_rope']::text[], false, true, 60, 'Media sentadilla y ondas rápidas con los brazos, alternas o a la vez.'),
  ('devil_press', 'Devil press', array['devil''s press', 'devils press', 'burpee con mancuernas y arrancada']::text[], 'functional', 'weight_reps', array['dumbbell']::text[], false, true, 120, 'Burpee sobre dos mancuernas y llevarlas desde el suelo hasta encima de la cabeza.'),
  ('db_snatch', 'Arrancada con mancuerna', array['dumbbell snatch', 'db snatch', 'snatch con mancuerna', 'arrancada a una mano']::text[], 'functional', 'weight_reps', array['dumbbell']::text[], true, true, 90, 'Del suelo a encima de la cabeza en un solo movimiento, con la fuerza de la cadera.'),
  ('power_clean', 'Cargada de potencia (power clean)', array['power clean', 'cargada', 'clean', 'cargada de fuerza', 'cargada al pecho']::text[], 'functional', 'weight_reps', array['barbell']::text[], false, true, 150, 'Barra del suelo a los hombros con un tirón explosivo y recepción en media sentadilla.'),
  ('hang_power_clean', 'Cargada colgante (hang power clean)', array['hang power clean', 'hang clean', 'cargada desde colgado', 'cargada desde rodillas']::text[], 'functional', 'weight_reps', array['barbell']::text[], false, true, 150, 'Como la power clean, empezando con la barra a la altura de los muslos.'),
  ('push_press', 'Push press', array['press con impulso', 'press de empuje']::text[], 'functional', 'weight_reps', array['barbell', 'dumbbell', 'kettlebell']::text[], false, true, 150, 'Pequeña flexión de rodillas y empuje de piernas que ayuda a subir la barra.'),
  ('bear_crawl', 'Paso de oso', array['bear crawl', 'gateo de oso', 'caminata de oso', 'cuadrupedia']::text[], 'functional', 'distance_time', array['bodyweight']::text[], false, true, 60, 'A cuatro patas con las rodillas a un palmo del suelo, avanza mano y pie contrarios.'),
  ('rope_climb', 'Subida a la cuerda', array['rope climb', 'trepa de cuerda', 'subir la cuerda', 'cuerda lisa']::text[], 'functional', 'reps', array['climbing_rope']::text[], false, true, 120, 'Usa las piernas para pinzar la cuerda y sube con los brazos por tramos.'),
  ('wall_walk', 'Wall walk', array['wall walks', 'subida a la pared', 'caminar por la pared', 'wall climb']::text[], 'functional', 'reps', array['bodyweight']::text[], false, true, 90, 'Desde tumbado boca abajo, sube los pies por la pared mientras las manos se acercan.')
on conflict (id) do update set
  name = excluded.name,
  aliases = excluded.aliases,
  category = excluded.category,
  tracking_type = excluded.tracking_type,
  equipment = excluded.equipment,
  is_unilateral = excluded.is_unilateral,
  is_compound = excluded.is_compound,
  default_rest_s = excluded.default_rest_s,
  technique_notes = excluded.technique_notes
where public.exercises.owner_id is null;

-- Músculos: se reescriben para que la semilla sea la fuente de verdad.
delete from public.exercise_muscles where exercise_id in ('muscle_up', 'pistol_squat', 'l_sit', 'handstand_hold', 'handstand_push_up', 'pike_push_up', 'archer_push_up', 'diamond_push_up', 'ring_dip', 'tuck_front_lever', 'dragon_flag', 'bench_dip', 'wall_sit', 'jump_squat', 'broad_jump', 'skater_jump', 'depth_jump', 'tuck_jump', 'jumping_lunge', 'plyo_push_up', 'pogo_jumps', 'med_ball_slam', 'med_ball_chest_pass', 'jumping_jacks', 'high_knees', 'battle_ropes', 'devil_press', 'db_snatch', 'power_clean', 'hang_power_clean', 'push_press', 'bear_crawl', 'rope_climb', 'wall_walk');

on conflict (exercise_id, muscle_id) do update set role = excluded.role;

-- Técnica (pasos clave y errores típicos).
update public.exercises e set
  technique_steps = v.steps,
  technique_mistakes = v.mistakes
from (values
  ('muscle_up', array['Cuélgate con agarre algo más estrecho que en la dominada y los hombros activos.', 'Tira de forma explosiva llevando la barra hacia la cadera, no hacia la barbilla.', 'Al pasar la barra, adelanta el pecho y gira las muñecas por encima.', 'Termina empujando como en un fondo hasta estirar los brazos y baja controlando.']::text[], array['Intentarlo sin hacer al menos 8 dominadas y 10 fondos limpios.', 'Pasar primero un brazo y luego el otro (chicken wing).', 'Tirar hacia la barbilla en vez de hacia el pecho bajo.']::text[]),
  ('pistol_squat', array['De pie sobre una pierna con la otra estirada al frente y los brazos delante.', 'Baja despacio llevando la cadera atrás y abajo, con el talón apoyado.', 'Llega abajo del todo sin que la pierna libre toque el suelo.', 'Sube empujando con todo el pie. Para aprender, baja a un banco o agárrate a un TRX.']::text[], array['Rodilla de apoyo hacia dentro.', 'Levantar el talón.', 'Caer abajo sin control y rebotar.']::text[]),
  ('l_sit', array['Apóyate en paralelas, paralettes o el suelo con los brazos estirados.', 'Empuja hacia abajo para subir los hombros y alejarlos de las orejas.', 'Sube las piernas estiradas al frente hasta la horizontal y aguanta.', 'Si cuesta, empieza con las rodillas dobladas (tuck L-sit).']::text[], array['Hundir los hombros.', 'Doblar los codos.', 'Dejar caer las piernas por debajo de la horizontal.']::text[]),
  ('handstand_hold', array['Para aprender, sube caminando con los pies por la pared, con el pecho mirando a ella.', 'Manos a la anchura de los hombros y dedos abiertos.', 'Empuja el suelo con los brazos estirados y el cuerpo recto, abdomen y glúteos apretados.', 'Baja caminando con las manos hacia la pared.']::text[], array['Arquear la espalda en forma de plátano.', 'Doblar los codos.', 'Subir de patada sin saber salir (aprende antes a caer girando).']::text[]),
  ('handstand_push_up', array['Colócate en pino de espaldas a la pared, con las manos a unos 20 cm de ella.', 'Baja controlando hasta que la cabeza toque una esterilla en el suelo.', 'Empuja hasta estirar los brazos con el cuerpo recto.', 'Si no sale, empieza con flexiones pica con los pies elevados.']::text[], array['Dejar caer la cabeza de golpe.', 'Manos muy abiertas.', 'Arquear mucho la espalda contra la pared.']::text[]),
  ('pike_push_up', array['Ponte en V invertida: manos y pies en el suelo y la cadera arriba.', 'Baja la cabeza hacia el suelo entre las manos doblando los codos.', 'Empuja hasta estirar los brazos. Pies en un banco para hacerlo más difícil.']::text[], array['Bajar la cadera y convertirlo en una flexión normal.', 'Abrir los codos a los lados.', 'Recorrido corto.']::text[]),
  ('archer_push_up', array['Ponte en plancha con las manos mucho más abiertas que los hombros.', 'Baja hacia una mano doblando ese codo mientras el otro brazo se queda casi estirado.', 'Empuja para volver al centro y alterna lados.']::text[], array['Hundir la cadera.', 'Doblar los dos brazos por igual.', 'Girar el tronco.']::text[]),
  ('diamond_push_up', array['Ponte en plancha con las manos juntas bajo el pecho, pulgares e índices formando un rombo.', 'Baja con los codos pegados al cuerpo hasta rozar las manos con el pecho.', 'Empuja hasta estirar los brazos con el cuerpo recto.']::text[], array['Abrir los codos hacia fuera.', 'Hundir la cadera.', 'Recorrido a medias.']::text[]),
  ('ring_dip', array['Sube a las anillas con los brazos estirados y las anillas pegadas al cuerpo.', 'Gira un poco las anillas hacia fuera arriba para estabilizarte.', 'Baja hasta que los hombros queden a la altura de los codos.', 'Empuja hasta estirar los brazos sin que las anillas se separen.']::text[], array['Dejar que las anillas se abran.', 'Bajar demasiado con los hombros adelantados.', 'Intentarlo sin dominar los fondos en paralelas.']::text[]),
  ('tuck_front_lever', array['Cuélgate con agarre prono a la anchura de los hombros.', 'Con los brazos estirados, lleva los hombros abajo y empuja la barra hacia la cadera.', 'Sube la cadera hasta que la espalda quede horizontal con las rodillas al pecho y aguanta.']::text[], array['Doblar los codos.', 'Dejar la cadera por debajo de los hombros.', 'Redondear la espalda sin tensión.']::text[]),
  ('dragon_flag', array['Túmbate en un banco y agárrate fuerte por detrás de la cabeza.', 'Sube el cuerpo recto hasta apoyarte solo en la parte alta de la espalda.', 'Baja despacio como una tabla, sin doblar la cadera, hasta casi tocar el banco.', 'Vuelve a subir o empieza solo con la bajada.']::text[], array['Doblar la cadera.', 'Apoyar el cuello en vez de los hombros.', 'Dejarse caer en vez de frenar.']::text[]),
  ('bench_dip', array['Siéntate en el borde del banco con las manos junto a la cadera.', 'Adelanta la cadera fuera del banco con las piernas dobladas o estiradas.', 'Baja doblando los codos hacia atrás hasta unos 90°.', 'Empuja hasta estirar los brazos.']::text[], array['Bajar demasiado y forzar el hombro.', 'Abrir los codos hacia fuera.', 'Alejar la cadera del banco.']::text[]),
  ('wall_sit', array['Apoya la espalda en la pared y adelanta los pies.', 'Baja hasta que rodillas y cadera formen 90°, con las rodillas sobre los tobillos.', 'Aguanta con la espalda pegada y respirando con normalidad.']::text[], array['Rodillas por delante de los pies.', 'Apoyar las manos en los muslos.', 'Quedarse muy alto.']::text[]),
  ('jump_squat', array['Pies a la anchura de los hombros y brazos listos para ayudar.', 'Baja a media sentadilla y salta lo más alto que puedas extendiendo cadera y rodillas.', 'Aterriza con las puntas primero, rodillas flexionadas y en la dirección de los pies.', 'Encadena la siguiente o haz una pausa entre saltos.']::text[], array['Aterrizar con las piernas rígidas.', 'Rodillas hacia dentro al caer.', 'Hacer muchas seguidas perdiendo altura y técnica.']::text[]),
  ('broad_jump', array['De pie con los pies a la anchura de la cadera.', 'Lleva los brazos atrás y la cadera atrás como en una bisagra.', 'Lanza los brazos adelante y salta hacia delante extendiendo todo el cuerpo.', 'Aterriza con las rodillas flexionadas y aguanta la posición un segundo.']::text[], array['Caer con las piernas rígidas.', 'Saltar hacia arriba en vez de hacia delante.', 'Aterrizar con las rodillas hacia dentro.']::text[]),
  ('skater_jump', array['Ponte sobre una pierna con la rodilla algo flexionada.', 'Salta lateralmente hacia el otro lado empujando con esa pierna.', 'Aterriza sobre la otra pierna, cruzando la libre por detrás, y estabilízate.', 'Cuenta una repetición por salto.']::text[], array['Aterrizar con la rodilla hacia dentro.', 'No frenar el aterrizaje.', 'Saltos cortos sin empujar.']::text[]),
  ('depth_jump', array['Súbete a un cajón bajo (30–45 cm).', 'Da un paso al vacío (no saltes) y cae con los dos pies a la vez.', 'En cuanto toques el suelo, salta lo más alto posible con el mínimo tiempo de contacto.', 'Pocas repeticiones y con descanso completo.']::text[], array['Cajón demasiado alto.', 'Quedarse en el suelo amortiguando antes de saltar.', 'Hacerlo cansado o sin base de fuerza.']::text[]),
  ('tuck_jump', array['De pie con los pies a la anchura de la cadera.', 'Salta lo más alto posible y lleva las rodillas hacia el pecho.', 'Estira las piernas antes de caer y aterriza con las rodillas flexionadas.']::text[], array['Bajar el pecho a las rodillas en vez de subir las rodillas.', 'Aterrizar rígido.', 'Encadenar sin control.']::text[]),
  ('jumping_lunge', array['Colócate en zancada con las dos rodillas a 90°.', 'Salta hacia arriba y cambia la posición de las piernas en el aire.', 'Aterriza en zancada con la otra pierna delante, amortiguando.', 'Cuenta una repetición por cada aterrizaje.']::text[], array['Golpear la rodilla trasera contra el suelo.', 'Rodilla delantera hacia dentro.', 'Inclinar el torso.']::text[]),
  ('plyo_push_up', array['Ponte en plancha alta con el cuerpo recto.', 'Baja como en una flexión y empuja con fuerza para despegar las manos.', 'Da una palmada si puedes y aterriza con los codos algo flexionados.']::text[], array['Aterrizar con los codos bloqueados.', 'Hundir la cadera.', 'Hacerlo sin dominar las flexiones normales.']::text[]),
  ('pogo_jumps', array['De pie con los pies juntos o a la anchura de la cadera.', 'Salta rebotando sobre las puntas con las rodillas casi estiradas.', 'Busca el mínimo tiempo en el suelo y un ritmo constante.']::text[], array['Doblar mucho las rodillas.', 'Apoyar los talones en cada salto.', 'Saltar alto y lento en vez de corto y rápido.']::text[]),
  ('med_ball_slam', array['Coge un balón de slam (que no bote) y súbelo por encima de la cabeza.', 'Ponte de puntillas estirando todo el cuerpo.', 'Lánzalo contra el suelo con fuerza doblando la cadera y las rodillas.', 'Recógelo con la espalda neutra y repite.']::text[], array['Usar un balón que bota y vuelve a la cara.', 'Redondear la espalda al recogerlo.', 'Lanzar solo con los brazos.']::text[]),
  ('med_ball_chest_pass', array['Ponte frente a una pared con el balón sujeto contra el pecho.', 'Da un paso adelante y empuja el balón con fuerza estirando los brazos.', 'Recógelo al rebote con los brazos flexionados y repite.']::text[], array['Lanzar con los codos muy abiertos.', 'Ponerse tan cerca que no da tiempo a recoger.', 'Arquear la espalda.']::text[]),
  ('jumping_jacks', array['De pie con los pies juntos y los brazos junto al cuerpo.', 'Salta abriendo las piernas y subiendo los brazos por encima de la cabeza.', 'Salta de nuevo para volver a la posición inicial; mantén un ritmo constante.']::text[], array['Aterrizar sobre los talones.', 'Brazos a medias.', 'Encorvar la espalda.']::text[]),
  ('high_knees', array['De pie con el torso erguido.', 'Corre en el sitio subiendo cada rodilla hasta la altura de la cadera.', 'Apoya sobre las puntas y acompaña con los brazos.']::text[], array['Echar el torso hacia atrás.', 'Rodillas bajas.', 'Apoyar los talones.']::text[]),
  ('battle_ropes', array['Coge un extremo de cuerda en cada mano y retrocede hasta que esté casi tensa.', 'Ponte en media sentadilla con el pecho alto y el abdomen firme.', 'Haz ondas rápidas subiendo y bajando los brazos, alternos o a la vez.', 'Mantén las ondas llegando hasta el anclaje.']::text[], array['Ponerse de pie recto y mover solo los brazos.', 'Ondas pequeñas que no llegan al final.', 'Encorvar la espalda.']::text[]),
  ('devil_press', array['Con una mancuerna en cada mano en el suelo, baja el pecho al suelo como en un burpee.', 'Sube a plancha y salta con los pies hacia las manos.', 'Con la espalda neutra, balancea las mancuernas entre las piernas y extiende la cadera.', 'Llévalas en un solo movimiento por encima de la cabeza con los brazos estirados.']::text[], array['Redondear la espalda al levantar las mancuernas.', 'Subirlas con los brazos en vez de con la cadera.', 'Arquear la lumbar arriba.']::text[]),
  ('db_snatch', array['Mancuerna en el suelo entre los pies; cógela con una mano y la espalda neutra.', 'Extiende la cadera y las rodillas con fuerza manteniendo la mancuerna cerca del cuerpo.', 'Tira con el codo alto y mete el cuerpo debajo para recibirla con el brazo estirado.', 'Bájala con control al hombro y luego al suelo.']::text[], array['Tirar con el brazo sin usar la cadera.', 'Alejar la mancuerna del cuerpo.', 'Recibir con el codo doblado.']::text[]),
  ('power_clean', array['Barra sobre la mitad del pie, agarre algo más ancho que los hombros y espalda tensa.', 'Sube la barra pegada a las piernas hasta medio muslo.', 'Extiende cadera, rodillas y tobillos de forma explosiva y encoge los hombros.', 'Mete los codos rápido por delante y recibe la barra en los hombros en media sentadilla.']::text[], array['Tirar con los brazos antes de extender la cadera.', 'Barra separada del cuerpo.', 'Recibir con los codos bajos.']::text[]),
  ('hang_power_clean', array['De pie con la barra en las manos, bájala a medio muslo haciendo bisagra de cadera.', 'Extiende la cadera de forma explosiva y encoge los hombros.', 'Tira con los codos altos y mete los codos por delante.', 'Recibe la barra en los hombros en media sentadilla y ponte de pie.']::text[], array['Doblar los codos antes de tiempo.', 'Echar la barra hacia delante con la cadera.', 'Recibir con las piernas rígidas.']::text[]),
  ('push_press', array['Barra apoyada en los hombros con los codos algo adelantados.', 'Flexiona un poco las rodillas con el torso vertical (dip).', 'Extiende las piernas con fuerza y aprovecha el impulso para empujar la barra arriba.', 'Bloquea los brazos con la barra sobre la cabeza y baja a los hombros.']::text[], array['Dip demasiado profundo, como una sentadilla.', 'Inclinar el torso hacia delante en el dip.', 'Arquear la lumbar arriba.']::text[]),
  ('bear_crawl', array['Ponte a cuatro patas y levanta las rodillas a un palmo del suelo.', 'Avanza a la vez mano y pie contrarios con pasos cortos.', 'Mantén la espalda plana y la cadera a la altura de los hombros.']::text[], array['Subir la cadera muy alto.', 'Mover mano y pie del mismo lado.', 'Pasos largos que hacen balancear la cadera.']::text[]),
  ('rope_climb', array['Coge la cuerda en alto y sube las rodillas al pecho.', 'Pinza la cuerda entre los pies (empeine de uno y planta del otro).', 'Ponte de pie sobre los pies y sube las manos; repite por tramos.', 'Baja mano a mano, frenando con los pies; nunca te dejes caer.']::text[], array['Subir solo con los brazos.', 'Bajar deslizándose: quema las manos.', 'Intentarlo sin colchoneta debajo.']::text[]),
  ('wall_walk', array['Túmbate boca abajo con los pies tocando la pared.', 'Sube a plancha y camina con los pies por la pared mientras acercas las manos.', 'Llega hasta casi tocar la pared con el pecho, con el cuerpo recto.', 'Baja deshaciendo los pasos con control.']::text[], array['Arquear la espalda arriba.', 'Bajar de golpe.', 'Manos muy abiertas.']::text[])
) as v (id, steps, mistakes)
where e.id = v.id and e.owner_id is null;
